package cn.zhuatech.marketingai.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CampaignFatigueService{public Result evaluate(Request r){double ctrDrop=r.baselineCtr()==0?0:Math.max(0,(r.baselineCtr()-r.currentCtr())*100/r.baselineCtr());int risk=(int)Math.round(Math.min(35,r.frequencySevenDays()*5)+Math.min(35,ctrDrop)+Math.min(20,r.unsubscribeRate()*5)+(r.audienceSaturation()>80?20:0)+(r.daysRunning()>30?10:0)-(r.creativeVariants()>3?10:0));risk=Math.max(0,Math.min(100,risk));List<String> actions=new ArrayList<>();if(r.frequencySevenDays()>5)actions.add("降低触达频次并设置冷却窗口");if(ctrDrop>20)actions.add("轮换创意和价值主张");if(r.audienceSaturation()>80)actions.add("扩展受众或排除已高频触达用户");String status=risk>=70?"ROTATE":risk>=35?"OPTIMIZE":"HEALTHY";if(actions.isEmpty())actions.add("活动疲劳信号较低，维持当前节奏");return new Result(Math.round(ctrDrop*10)/10.0,risk,status,actions);}
 public record Request(@DecimalMin("0") double frequencySevenDays,@DecimalMin("0") double baselineCtr,@DecimalMin("0") double currentCtr,@DecimalMin("0") double unsubscribeRate,@Min(0) @Max(100) int audienceSaturation,@Min(0) int daysRunning,@Min(1) int creativeVariants){}public record Result(double ctrDropRate,int fatigueRisk,String status,List<String> actions){} }
